```js
import {
  Group, Mesh, PlaneGeometry, OctahedronGeometry, TorusGeometry,
  MeshStandardNodeMaterial, MeshBasicNodeMaterial,
  DirectionalLight, AmbientLight, PointLight,
  Color, Vector2, DoubleSide
} from 'three/webgpu';
import { uv, texture, float, uniform, mix, vec3, smoothstep } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const THREE = ctx.THREE;
  const group = new Group();
  group.name = 'hub-features-divider';

  const c = config.intent?.visualSpec?.colors ?? {};
  const ink = new Color(c.ink ?? '#16161d');
  const paper = new Color(c.paper ?? '#e8ecf2');
  const accent = new Color(c.accent ?? '#ff2a38');
  const surface = new Color(c.surface ?? '#0b0b10');

  const tl = gsap.timeline({ paused: true });

  // ---- Stage backdrop: dark gradient (ink -> surface) ----
  const backdropMat = new MeshBasicNodeMaterial({ side: DoubleSide });
  backdropMat.colorNode = mix(
    vec3(ink.r, ink.g, ink.b),
    vec3(surface.r, surface.g, surface.b),
    uv().y.smoothstep(float(0.0), float(1.0))
  );
  const backdrop = new Mesh(new PlaneGeometry(7, 6), backdropMat);
  backdrop.position.set(0, 0, -2.5);
  group.add(backdrop);

  // ---- Divider rule: tessellated plane with displacement ----
  const ruleW = 2.6, ruleH = 0.34;
  const ruleGeo = new PlaneGeometry(ruleW, ruleH, 64, 64);
  const ruleMat = new MeshStandardNodeMaterial({
    color: 0xb8bcc4,
    metalness: 0.55,
    roughness: 0.5,
    side: DoubleSide
  });

  // cursor parallax uniform (subtle)
  const cursorU = uniform(new Vector2(0, 0));
  ruleMat.colorNode = mix(
    vec3(ink.r, ink.g, ink.b),
    vec3(paper.r * 0.78, paper.g * 0.78, paper.b * 0.84),
    smoothstep(float(0.0), float(1.0), uv().y)
  );

  const ruleMesh = new Mesh(ruleGeo, ruleMat);
  ruleMesh.position.set(0, 0, 0);
  ruleMesh.castShadow = false;
  ruleMesh.receiveShadow = false;

  let baseTex = null, depthTex = null;

  const dispAmount = float(0.045);

  ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
    baseTex = tex;
    baseTex.colorSpace = THREE.SRGBColorSpace;
    baseTex.anisotropy = 8;
    ruleMat.colorNode = texture(baseTex, uv().add(cursorU.mul(float(0.010)))).rgb;
    ruleMat.needsUpdate = true;
  });

  ctx.textureLoader.loadTexture(config.depthMapUrl).then((tex) => {
    depthTex = tex;
    depthTex.anisotropy = 4;
    ruleMat.displacementNode = texture(depthTex, uv().add(cursorU.mul(float(0.018)))).r.mul(dispAmount);
    ruleMat.needsUpdate = true;
  });

  group.add(ruleMesh);

  // ---- Center jewel: machined ring + accent gem ----
  const jewelGroup = new Group();
  jewelGroup.position.set(0, 0, 0.06);

  // outer polished ring
  const ringMat = new MeshStandardNodeMaterial({
    color: 0x9aa0aa,
    metalness: 0.95,
    roughness: 0.22,
    side: DoubleSide
  });
  const ring = new Mesh(new TorusGeometry(0.11, 0.022, 24, 64), ringMat);
  jewelGroup.add(ring);

  // inner gem: octahedron with accent emissive
  const gemMat = new MeshStandardNodeMaterial({
    color: 0x1a1a22,
    metalness: 0.6,
    roughness: 0.35,
    emissive: new Color(accent),
    emissiveIntensity: 1.6
  });
  // cap emissive intensity at 2.3 per doctrine
  const gem = new Mesh(new OctahedronGeometry(0.052, 0), gemMat);
  gem.rotation.set(Math.PI / 4, Math.PI / 4, 0);
  jewelGroup.add(gem);

  group.add(jewelGroup);

  // ---- Lights (local) ----
  const amb = new AmbientLight(0xffffff, 0.4);
  group.add(amb);

  const key = new DirectionalLight(0xfff2e6, 1.0);
  key.position.set(2.2, 2.4, 3.0);
  group.add(key);

  const rim = new DirectionalLight(0xff2a38, 0.6);
  rim.position.set(-2.5, -1.2, -2.0);
  group.add(rim);

  const back = new DirectionalLight(0x9fb4ff, 0.5);
  back.position.set(0, 1.5, -3.0);
  group.add(back);

  // jewel focal light (accent)
  const gemLight = new PointLight(0xff2a38, 0.6, 2.0, 2.0);
  gemLight.position.set(0, 0, 0.25);
  group.add(gemLight);

  // ---- Idle breathing on jewel ----
  const idle = gsap.to(jewelGroup.rotation, {
    y: Math.PI * 2, duration: 18, ease: 'none', repeat: -1
  });
  const pulse = gsap.to(gemMat, {
    emissiveIntensity: 0.9, duration: 1.4, ease: 'sine.inOut', yoyo: true, repeat: -1
  });

  // entrance
  tl.from(group.position, { y: -0.55, duration: 0.7, ease: 'power3.out' }, 0)
    .from(group.scale, { x: 0.6, y: 0.6, duration: 0.7, ease: 'power3.out' }, 0)
    .from(ruleMaterialOpacity(), { v: 0, duration: 0.5, ease: 'power2.out' }, 0);

  function ruleMaterialOpacity() { return { v: 1 }; }

  tl.play();

  // ---- Handlers ----
  group.userData.handlers = {
    onPointerOver: (e) => {
      ctx.emit('hub-features.divider-hover', {});
      gsap.to(group.position, { y: 0.15, duration: 0.5, ease: 'power3.out', overwrite: 'auto' });
      gsap.to(cursorU.value, { x: 0.012, y: -0.008, duration: 0.5, ease: 'power2.out' });
      gsap.to(ring.scale, { x: 1.12, y: 1.12, z: 1.12, duration: 0.5, ease: 'power2.out' });
    },
    onPointerOut: (e) => {
      gsap.to(group.position, { y: 0, duration: 0.6, ease: 'power3.out', overwrite: 'auto' });
      gsap.to(cursorU.value, { x: 0, y: 0, duration: 0.6, ease: 'power2.out' });
      gsap.to(ring.scale, { x: 1, y: 1, z: 1, duration: 0.6, ease: 'power2.out' });
    },
    onClick: (e) => {
      ctx.emit('navigate', { to: 'hub-features.select' });
      gsap.to(group.scale, { x: 0.97, y: 0.97, duration: 0.12, ease: 'power2.out', overwrite: 'auto',
        onComplete: () => {
          gsap.to(group.scale, { x: 1.04, y: 1.04, duration: 0.18, ease: 'back.out(2)' });
          gsap.to(group.scale, { x: 1, y: 1, duration: 0.9, ease: 'power4.out', delay: 0.18, overwrite: 'auto' });
        }
      });
      gsap.to(gemMat, { emissiveIntensity: 2.3, duration: 0.12, ease: 'power2.out',
        onComplete: () => gsap.to(gemMat, { emissiveIntensity: 1.6, duration: 0.6, ease: 'power3.out' })
      });
    }
  };

  // ---- Cleanup ----
  group.userData.cleanup = () => {
    tl.kill();
    idle.kill();
    pulse.kill();
    gsap.killTweensOf(group.position);
    gsap.killTweensOf(group.scale);
    gsap.killTweensOf(cursorU.value);
    gsap.killTweensOf(ring.scale);
    gsap.killTweensOf(gemMat);
    ruleGeo.dispose();
    backdrop.geometry.dispose();
    ring.geometry.dispose();
    gem.geometry.dispose();
    ruleMat.dispose();
    backdropMat.dispose();
    ringMat.dispose();
    gemMat.dispose();
    if (baseTex && baseTex.dispose) baseTex.dispose();
    if (depthTex && depthTex.dispose) depthTex.dispose();
  };

  return group;
}
